WITH valid_shipments AS (SELECT *, DATE_ADD(shipped_date, 5) AS shipped_date_plus_5d FROM shipments WHERE MONTH(delivered_date) IN (6, 11, 12) AND status IN ('LOST', 'DELIVERED')), CarrierGroupSummary AS (SELECT CASE WHEN carrier IN ('DHL', 'FedEx') THEN 'tier_1' ELSE 'other' END AS carrier_group, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(status))) AS status_values FROM valid_shipments GROUP BY CASE WHEN carrier IN ('DHL', 'FedEx') THEN 'tier_1' ELSE 'other' END) SELECT carrier_group, status_values FROM CarrierGroupSummary;
